import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import styled from 'styled-components';
import { User, Project } from '../types';
import { apiService } from '../services/api';

const SidebarContainer = styled.div`
  width: 320px;
  background-color: #2c3e50;
  color: white;
  padding: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  height: 100vh;
`;

const UserSection = styled.div`
  padding: 20px;
  background-color: #34495e;
  border-bottom: 1px solid #4a5f7a;
`;

const UserInfo = styled.div`
  margin-bottom: 15px;
`;

const UserEmail = styled.div`
  font-weight: 600;
  margin-bottom: 8px;
  font-size: 16px;
`;

const UserBalance = styled.div`
  font-size: 14px;
  color: #bdc3c7;
  margin-bottom: 8px;
`;

const BalanceAmount = styled.span`
  font-weight: 600;
  color: #2ecc71;
`;

const UserActions = styled.div`
  display: flex;
  gap: 10px;
`;

const ActionButton = styled.button`
  flex: 1;
  padding: 8px 12px;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: 12px;
  font-weight: 500;
  transition: background-color 0.2s;
`;

const TopUpButton = styled(ActionButton)`
  background-color: #3498db;
  color: white;

  &:hover {
    background-color: #2980b9;
  }
`;

const LogoutButton = styled(ActionButton)`
  background-color: #e74c3c;
  color: white;

  &:hover {
    background-color: #c0392b;
  }
`;

const ProjectsSection = styled.div`
  flex: 1;
  padding: 20px;
  overflow-y: auto;
`;

const SectionTitle = styled.h3`
  margin: 0 0 20px 0;
  font-size: 18px;
  color: #ecf0f1;
`;

const SearchContainer = styled.div`
  margin-bottom: 20px;
`;

const SearchInput = styled.input`
  width: 100%;
  padding: 10px 12px;
  border: 1px solid #4a5f7a;
  border-radius: 6px;
  background-color: #34495e;
  color: white;
  font-size: 14px;

  &::placeholder {
    color: #95a5a6;
  }

  &:focus {
    outline: none;
    border-color: #3498db;
    background-color: #2c3e50;
  }
`;

const FilterContainer = styled.div`
  margin-bottom: 20px;
`;

const FilterSelect = styled.select`
  width: 100%;
  padding: 8px 12px;
  border: 1px solid #4a5f7a;
  border-radius: 6px;
  background-color: #34495e;
  color: white;
  font-size: 14px;

  &:focus {
    outline: none;
    border-color: #3498db;
  }
`;

const ProjectsList = styled.div`
  display: flex;
  flex-direction: column;
  gap: 12px;
`;

const ProjectItem = styled.div<{ active?: boolean }>`
  padding: 15px;
  background-color: ${props => props.active ? '#3498db' : '#34495e'};
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s;
  border: 1px solid ${props => props.active ? '#2980b9' : 'transparent'};

  &:hover {
    background-color: ${props => props.active ? '#2980b9' : '#4a5f7a'};
    transform: translateY(-1px);
  }
`;

const ProjectTitle = styled.div`
  font-weight: 600;
  margin-bottom: 6px;
  font-size: 14px;
  color: ${props => props.color || '#ecf0f1'};
`;

const ProjectMeta = styled.div`
  font-size: 12px;
  color: #bdc3c7;
  margin-bottom: 4px;
`;

